SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5047247441ba8ca5148602bf0116a6c308eb295b/content/books/zizhi-tongjian/vol-288/year-0948/part-05/sources/library/jiuwudaishi-101-july-948/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002457；EPUB电子本，纸本及异文待核", "id": "bd9d66b0-d1d2-548e-b762-4480c5d27c94"}, {"title": "宋史·巻四百七十九", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5047247441ba8ca5148602bf0116a6c308eb295b/content/books/zizhi-tongjian/vol-288/year-0948/part-05/sources/library/songshi-479-wang-zhaoyuan-early/source.txt", "note": "《宋史》巻四百七十九，段落 songshi-9c6e46fee832-p074978；EPUB电子本，纸本及异文待核", "id": "a6338a18-1634-5507-beef-92edbf577262"}, {"title": "新五代史·卷六十四", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5047247441ba8ca5148602bf0116a6c308eb295b/content/books/zizhi-tongjian/vol-288/year-0948/part-05/sources/library/xinwudaishi-064-wang-zhaoyuan-early/source.txt", "note": "《新五代史》卷六十四，段落 xin-wudaishi-b08f244b9241-p003247；EPUB电子本，纸本及异文待核", "id": "71c48d02-f978-5585-bd21-de57e167b022"}, {"title": "新五代史·卷六十四", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5047247441ba8ca5148602bf0116a6c308eb295b/content/books/zizhi-tongjian/vol-288/year-0948/part-05/sources/library/xinwudaishi-064-zhang-ye-fall/source.txt", "note": "《新五代史》卷六十四，段落 xin-wudaishi-b08f244b9241-p003239；EPUB电子本，纸本及异文待核", "id": "3f1464f7-a574-5fd7-89e5-a4a073e0999b"}, {"title": "新五代史·卷六十九", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5047247441ba8ca