ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "王景崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员。937年担任引进使，受命劝秘琼接受任命。史书记载他是邢州人。", "biography": null, "status": "draft", "id": "5f673eda-0daa-5174-926f-dca3e0982614"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "高从诲", "aliases": ["高從誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷273同光三年条所见人物：高从诲。", "biography": null, "status": "draft", "id": "361de308-8df0-56e4-ac98-81f6b9297e26"}, {"name": "刘扶", "aliases": ["劉扶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荆南牙将。948年高从诲请求恢复与后汉往来时，派刘扶到后汉朝廷请罪，《旧五代史》六月条记载这次出使。生卒年未载。", "biography": null, "status": "draft", "id": "9db314b8-73df-5c6b-9b58-a4b18bcbde9c"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "尚洪迁", "aliases": ["尚洪遷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉将领。948年《资治通鉴》记其任宁江节度使、侍卫步军都指挥使，四月乙未被任为西面行营都虞候；《旧五代史》写西南面行营。生卒年尚未录入。", "biography": null, "status": "draft", "id": "014bf6c4-c82b-5b88-9792-2530cf2dd254"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "张业", "aliases": ["張業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：张业。", "biography": null, "status": "draft", "id": "79f0f8ee-f0c7-5ba0-a428-aacf648664be"}, {"name": "张继昭", "aliases": ["張繼昭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀张业之子，史书记为检校左仆射，喜好击剑，曾与僧人归信寻找擅长剑术的人。孙汉韶向孟昶指控父子谋反；本段没有证实这项指控。生卒年未载，本段没有明确记载张继昭被杀。", "biography": null, "status": "draft", "id": "7464a8a6-f024-5275-b9fc-ebbe210d94be"}, {"name": "归信", "aliases": ["歸信"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》记载的僧人，曾与后蜀张继昭寻找擅长剑术的人。史书没有说明他是否参与谋反。生卒年及其他身份未载。", "biography": null, "status": "draft", "id": "e400d380-f064-5e55-a7eb-cce289c3ab74"}, {"name": "孙汉韶", "aliases": ["孫漢韶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：孙汉韶，武定节度使、合兵奏者。", "biography": null, "status": "draft", "id": "5e4dd4c6-73f4-51a3-a55b-930f6b95eac2"}, {"name": "李昊", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光三年条所见人物：李昊。", "biography": null, "status": "draft", "id": "ecf7855b-2568-576c-b0b9-58e6b1f120fa"}, {"name": "安思谦", "aliases": ["安思謙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安思谦，茶酒库使、曾事藩邸者。", "biography": null, "status": "draft", "id": "6ec752d6-91f9-5760-8ea8-c552e6369345"}, {"name": "王处回", "aliases": ["王處回"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王处回，为税官请免的中门副使。", "biography": null, "status": "draft", "id": "159fd2b3-759b-522a-a971-11356c6fe970"}, {"name": "王德钧", "aliases": ["王德鈞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀王处回之子。《资治通鉴》在948年条追述他骄横，但没有列明具体行为和发生日期。生卒年未载。", "biography": null, "status": "draft", "id": "4ee88af6-770a-5214-a8ec-961f5fe673a1"}, {"name": "高延昭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀官员。948年任普丰库使，孟昶原想任命他与王昭远为枢密使，因二人资历和地位较低，改任通奏使、知枢密院事。生卒年未载。", "biography": null, "status": "draft", "id": "23555921-c9e7-5941-a4d0-9976d43ac9a2"}, {"name": "王昭远", "aliases": ["王昭遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "成都人，后蜀官员。年少时跟随僧人智諲进入孟知祥府中，后来被留下侍奉孟昶；《新五代史》《宋史》记当时十三岁。948年由茶酒库使任通奏使、知枢密院事，获委机务和府库财物支配。没有据十三岁反推出生年。", "biography": null, "status": "draft", "id": "49c83873-4e4d-515e-9f4b-ebbf460d53fd"}, {"name": "孟知祥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：孟知祥。", "biography": null, "status": "draft", "id": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"name": "智諲", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "成都东郭僧人。《新五代史》《宋史》在追述王昭远早年经历时记载，王昭远曾作为童子跟随智諲进入孟知祥府中。具体发生年及智諲生卒年未载。", "biography": null, "status": "draft", "id": "8270a5f5-f768-5d8d-9a98-87f34e031bcf"}, {"name": "郭从义", "aliases": ["郭從義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任郑州防御使。六月刘知远令他先入大梁清理宫禁，并秘密命令他杀李从益与王淑妃。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1119f609-51af-51d0-9244-ca7ac5b42d47"}, {"name": "白文珂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋代州刺史。944年九月在七里烽击败契丹；新史记丙子，旧史壬辰记录太原奏报。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "4144a98b-cc52-5b8e-afec-6ad9ed55b845"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
