dynasty": "五代十国", "description": "后汉下诏派使者慰抚高从诲。", "phases": [], "location_name": "后汉朝廷、荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5fe69231-bfab-59d4-bb27-cb94389acfeb"}, {"title": "尚洪迁攻打长安，受重伤后去世", "start_year": 948, "end_year": 948, "time_original": "948年六月条所载，具体日未载", "dynasty": "五代十国", "description": "尚洪迁攻打长安，受重伤后去世。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ac6e05ce-e22c-5778-abde-1101459df6bd"}, {"title": "李谷任西南面行营都转运使", "start_year": 948, "end_year": 948, "time_original": "948年七月壬子，据《旧五代史》；《资治通鉴》只记七月", "dynasty": "五代十国", "description": "李谷任西南面行营都转运使。", "phases": [], "location_name": "西南面行营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b527b828-6b51-59d7-aba3-5daf51f55bdc"}, {"title": "后汉给枢密使郭威加同平章事", "start_year": 948, "end_year": 948, "time_original": "948年七月庚申", "dynasty": "五代十国", "description": "后汉给枢密使郭威加同平章事。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fd3dcf6b-fcaf-5e68-8529-fe8f7a998db7"}, {"title": "史书记载张业强买田宅，并在家中私设牢狱", "start_year": null, "end_year": null, "time_original": "948年七月张业被杀之前的追叙，具体发生年月未载", "dynasty": "五代十国", "description": "《资治通鉴》追述张业强行购买他人的田宅，在私宅藏匿逃亡者，又设牢狱拘禁欠债者；有的人被关多年，甚至死在狱中。", "phases": [], "location_name": "后蜀、张业私宅", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "394042fa-4893-549d-9e8c-282c9fcb22be"}, {"title":